												className="button-ghost"
												title="Close details"
												size="icon"
											>
												<CustomIcon
													id="close"
													className="h-6 w-6"
												/>
											</Button>
										</Tooltip>
                                    </div>

                                    <div className="flex-1 space-y-1">
                                        {formError && (
