					<AutoStartToggle
						autoStart={formData.autoStart ?? false}
						onChange={(value) => onUpdateForm({ autoStart: value })}
					/>

					<FormActions
						onCancel={onCancel}
						onSubmit={onSubmit}
						isUpdate={isEditMode}
						formData={formData}
					/>
				</div>
			</div>
		);
	},
);

