                                ) : (
                                    <div className="flex flex-col justify-between">
                                        <div
                                            ref={scrollContainerRef}
                                            className={`overflow-y-auto max-h-[calc(100vh-13rem)] ${hasScrollbar ? 'pr-2' : ''}`}
