        <button
          className={clsx("px-2", {
            "text-grey-400 dark:text-grey-700": !table.getCanNextPage(),
            "dark:text-white": table.getCanNextPage(),
          })}
          onClick={() => table.nextPage()}
          disabled={!table.getCanNextPage()}
        >
          {">"}
        </button>
        <button
          className={clsx("px-2", {
            "text-grey-400 dark:text-grey-700": !table.getCanNextPage(),
            "dark:text-white": table.getCanNextPage(),
          })}
          onClick={() => table.setPageIndex(table.getPageCount() - 1)}
          disabled={!table.getCanNextPage()}
        >
          {">>"}
        </button>
      </div>
    </div>
  );
}

