          clipPath="url(#clip0_106_4278)"
        >
          <path
            stroke="currentColor"
            d="M7.646 1.28a6.667 6.667 0 11-4.311 1.94M8 4.333V8l2 1.333"
          ></path>
          <path
            stroke="currentColor"
            d="M.701 3.693l3.22-.863.776 2.898"
