    figi: str | None = Field(default=None, description="FIGI of the bond.")
    cusip: str | None = Field(
        default=None,
        description="CUSIP of the bond.",
    )
    coupon_rate: float | None = Field(
        default=None,
        description="Coupon rate of the bond.",
