This module provides Pydantic models for validating JSON content in the
openapi_extra.mcp_config field of FastAPI route definitions.
"""

import re
from enum import Enum
from typing import Any

from fastmcp.utilities.logging import get_logger
from pydantic import BaseModel, Field, field_validator, model_validator

logger = get_logger(__name__)


class MCPType(str, Enum):
    """Valid MCP type values."""

    TOOL = "tool"
    RESOURCE = "resource"
    RESOURCE_TEMPLATE = "resource_template"


class HTTPMethod(str, Enum):
    """Valid HTTP methods for route configuration."""

    GET = "GET"
    POST = "POST"
    PUT = "PUT"
    PATCH = "PATCH"
    DELETE = "DELETE"
    HEAD = "HEAD"
    OPTIONS = "OPTIONS"
    ALL = "*"


class ArgumentDefinitionModel(BaseModel):
    """Model for validating prompt argument definitions."""

    name: str = Field(..., description="Name of the argument")
    type: str = Field(default="str", description="Type of the argument")
    default: Any | None = Field(
        default=None, description="Default value for the argument"
    )
    description: str | None = Field(
        default=None, description="Description of the argument"
    )

    @field_validator("name")
    @classmethod
    def validate_name(cls, v: str) -> str:
        """Validate argument name is a valid identifier."""
        if not v:
            raise ValueError("Argument name cannot be empty")
        if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", v):
            raise ValueError(f"Argument name '{v}' must be a valid Python identifier")
        return v

    @field_validator("type")
    @classmethod
    def validate_type(cls, v: str) -> str:
        """Validate type is a recognized type string."""
        valid_types = {
            "str",
            "string",
            "int",
            "integer",
            "float",
            "bool",
            "boolean",
            "list",
            "dict",
            "any",
            "Any",
        }
        if v not in valid_types:
            raise ValueError(
                f"Type '{v}' not recognized. Valid types: {', '.join(sorted(valid_types))}"
            )
        return v


class PromptConfigModel(BaseModel):
    """Model for validating individual prompt configurations."""

    name: str | None = Field(
        default=None, description="Name of the prompt (auto-generated if not provided)"
    )
    description: str | None = Field(
        default=None, description="Description of the prompt"
    )
    content: str = Field(description="Template content with {variable} placeholders")
    arguments: list[ArgumentDefinitionModel] = Field(
        default_factory=list, description="Argument definitions for the prompt"
    )
    tags: list[str] = Field(
        default_factory=list, description="Tags for categorizing the prompt"
    )

    @field_validator("content")
    @classmethod
    def validate_content(cls, v: str) -> str:
        """Validate content is not empty and contains valid template syntax."""
        if not v.strip():
            raise ValueError("Prompt content cannot be empty")

        # Check for unmatched braces
        open_braces = v.count("{")
        close_braces = v.count("}")
        if open_braces != close_braces:
            raise ValueError(
                f"Unmatched braces in prompt content: {open_braces} opening, {close_braces} closing"
            )

        return v

    @field_validator("name")
    @classmethod
    def validate_name(cls, v: str | None) -> str | None:
        """Validate prompt name if provided."""
        if v is not None:
            if not v.strip():
                raise ValueError("Prompt name cannot be empty string")
            # Check for valid identifier-like name
            if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", v.strip()):
                raise ValueError(f"Prompt name '{v}' should be a valid identifier")
        return v

    @field_validator("tags")
    @classmethod
    def validate_tags(cls, v: list[str]) -> list[str]:
        """Validate tags are non-empty strings."""
        validated_tags = []
        for tag in v:
            if not isinstance(tag, str):
                raise ValueError(f"Tag must be a string, got {type(tag)}")
            if not tag.strip():
                raise ValueError("Tag cannot be empty string")
            validated_tags.append(tag.strip())
        return validated_tags


class MCPConfigModel(BaseModel):
    """Model for validating the main MCP configuration structure."""

    expose: bool | None = Field(
        default=None, description="Whether to expose this route (False = exclude)."
    )
    mcp_type: MCPType | None = Field(
        default=None, description="MCP type classification for the route."
    )
    methods: list[HTTPMethod] | None = Field(
        default=None, description="HTTP methods to include for this route."
    )
    prompts: list[PromptConfigModel] = Field(
        default_factory=list, description="Prompt configurations for this route."
    )
    exclude_args: list[str] | None = Field(
        default=None, description="List of argument names to exclude from this route."
    )

    @field_validator("methods", mode="before")
    @classmethod
    def validate_methods(cls, v: str | list[str] | None) -> list[HTTPMethod] | None:
        """Normalize and validate HTTP methods."""
        if v is None:
            return None

        # Handle single string
        if isinstance(v, str):
            v = [v]

        if not isinstance(v, list):
            raise ValueError("methods must be a list of strings")

        # If '*' is present, it should be the only method
        if "*" in v and len(v) > 1:
            raise ValueError("Method '*' cannot be mixed with other HTTP methods.")

        # Validate each method
        validated_methods = []
        for method in v:
            method_str = str(method).upper().strip() if method != "*" else "*"
            try:
                validated_methods.append(HTTPMethod(method_str))
            except ValueError as exc:
                valid_methods = [m.value for m in HTTPMethod]
                raise ValueError(
                    f"Invalid HTTP method '{method}'. Valid methods: {', '.join(valid_methods)}"
                ) from exc

        # Remove duplicates while preserving order
        seen = set()
        unique_methods = []
        for method in validated_methods:
            if method not in seen:
                seen.add(method)
                unique_methods.append(method)

        return unique_methods if unique_methods else None

    @model_validator(mode="after")
    def validate_config_consistency(self) -> "MCPConfigModel":
        """Validate overall configuration consistency."""
        # If expose is False, other configurations don't matter much, but we still validate them
        if self.expose is False:
            # Could add warnings here if other fields are set when expose=False
            pass

        # Validate prompt names are unique within this config
        if self.prompts:
            prompt_names = []
            for prompt in self.prompts:
                if prompt.name:
                    prompt_names.append(prompt.name)

            # Check for duplicate names
            if len(prompt_names) != len(set(prompt_names)):
                duplicates = [
                    name for name in prompt_names if prompt_names.count(name) > 1
                ]
                raise ValueError(f"Duplicate prompt names found: {set(duplicates)}")

        return self

    def to_dict(self) -> dict[str, Any]:
        """Convert to dictionary format compatible with existing code."""
        return self.model_dump(exclude_none=True)


def validate_mcp_config(
    config_dict: dict[str, Any], *, strict: bool = True
) -> MCPConfigModel:
    """
    Validate an MCP configuration dictionary.

    Args:
        config_dict: The configuration dictionary to validate
        strict: If True, raise validation errors. If False, log warnings and return best-effort model.

    Returns:
        Validated MCPConfigModel instance

    Raises:
        ValidationError: If validation fails and strict=True
    """
    try:
        return MCPConfigModel.model_validate(config_dict)
    except Exception as exc:  # pylint: disable=broad-except
        if strict:
            raise exc from exc
        logger.warning("MCP config validation failed ->", exc_info=exc)
        return MCPConfigModel()


def is_valid_mcp_config(config_dict: dict[str, Any]) -> bool | Exception:
    """
    Check if a configuration dictionary is valid without raising exceptions.

    Args:
        config_dict: The configuration dictionary to check

    Returns:
        True if valid, False otherwise
    """
    try:
        validate_mcp_config(config_dict, strict=True)
        return True
    except Exception as exc:
        return exc

"""Custom Prompt classes for FastMCP."""

from typing import Any

from fastmcp.exceptions import PromptError
from fastmcp.prompts.prompt import Prompt
from mcp.types import PromptMessage, TextContent


class StaticPrompt(Prompt):
    """A prompt that is a static string template."""

    content: str

    async def render(
        self,
        arguments: dict[str, Any] | None = None,
    ) -> list[PromptMessage]:
        """Render the prompt with arguments."""
        args = arguments or {}

        # Validate required arguments
        if self.arguments:
            required = {arg.name for arg in self.arguments if arg.required}
            provided = set(args)
            missing = required - provided
            if missing:
                raise PromptError(f"Missing required arguments: {missing}")

        try:
            rendered_content = self.content.format(**args)
            return [
                PromptMessage(
                    role="user", content=TextContent(type="text", text=rendered_content)
                )
            ]
        except KeyError as e:
            raise PromptError(f"Missing argument for formatting: {e}") from e

"""Tool registry for managing MCP tools and tool discovery."""

from collections import defaultdict
from collections.abc import Mapping
from dataclasses import dataclass, field

from fastmcp.server.openapi import OpenAPITool

from openbb_mcp_server.models.tools import ToggleResult


@dataclass
class ToolRegistry:
    """Keeps track of categories, subcategories and tool instances."""

    _by_category: dict[str, dict[str, dict[str, OpenAPITool]]] = field(
        default_factory=lambda: defaultdict(lambda: defaultdict(dict))
    )
    _by_name: dict[str, OpenAPITool] = field(default_factory=dict)

    def register_tool(
        self, *, category: str, subcategory: str, tool_name: str, tool: OpenAPITool
    ) -> None:
        """Register a tool in the registry."""
        self._by_category[category][subcategory][tool_name] = tool
        self._by_name[tool_name] = tool

    def get_categories(self) -> Mapping[str, Mapping[str, Mapping[str, OpenAPITool]]]:
        """Get immutable view of all categories and their tools."""
        return self._by_category

    def get_category_tools(
        self, category: str, subcategory: str | None = None
    ) -> dict[str, OpenAPITool]:
        """Get tools in a category, optionally filtered by subcategory."""
        if subcategory is None:
            # flatten all subcategories
            return {
                name: tool
                for subcat_tools in self._by_category.get(category, {}).values()
                for name, tool in subcat_tools.items()
            }
        return self._by_category.get(category, {}).get(subcategory, {})

    def get_tool(self, tool_name: str) -> OpenAPITool | None:
        """Get a tool by name."""
        return self._by_name.get(tool_name)

    def get_category_subcategories(
        self, category: str
    ) -> dict[str, dict[str, OpenAPITool]] | None:
        """Get all subcategories for a specific category."""
        return self._by_category.get(category)

    def toggle_tools(self, tool_names: list[str], enable: bool) -> ToggleResult:
        """Enable or disable a list of tools, returning a status message."""
        successful, failed = [], []

        for name in tool_names:
            tool = self._by_name.get(name)
            if tool:
                (tool.enable if enable else tool.disable)()
                successful.append(name)
            else:
                failed.append(name)

        action = "activated" if enable else "deactivated"
        parts: list[str] = []

        if successful:
            parts.append(f"{action.capitalize()}: {', '.join(successful)}")
        if failed:
            parts.append(f"Not found: {', '.join(failed)}")

        message = " ".join(parts) if parts else "No tools processed."

        return ToggleResult(
            action=action,
            successful=successful,
            failed=failed,
            message=message,
        )

    def clear(self) -> None:
        """Clear the registry."""
        self._by_category.clear()
        self._by_name.clear()

"""Configuration service for MCP Server."""

import json
import logging
import os
from pathlib import Path
from typing import Any, Union, get_args, get_origin

from openbb_core.app.constants import OPENBB_DIRECTORY
from openbb_core.app.model.abstract.singleton import SingletonMeta

from openbb_mcp_server.models.settings import MCPSettings


def _merge_nested_dict(base: dict[str, Any], override: dict[str, Any]) -> None:
    """Merge override dict into base dict."""
    for key, value in override.items():
        if key in base and isinstance(base[key], dict) and isinstance(value, dict):
            # Merge nested dictionaries
            base[key].update(value)
        else:
            # Direct replacement for non-dict values or new keys
            base[key] = value


class MCPService(metaclass=SingletonMeta):
    """MCP Service. This class is a singleton.

    Manages the MCP settings and merging with command line arguments.
    It handles loading settings from the ~/.openbb_platform/mcp_settings.json file,
    environment variables, and command-line arguments, giving priority to the latter.

    Priority order (highest to lowest):
        1. Command line arguments (cli_overrides)
        2. Environment variables
        3. Configuration file (already loaded in self._mcp_settings)
        4. Default values (from MCPSettings model)
    """

    MCP_SETTINGS_PATH: Path = OPENBB_DIRECTORY / "mcp_settings.json"

    def __init__(self, **kwargs: Any) -> None:
        """Initialize MCP service, loading settings from the configuration file."""
        self._mcp_settings = self._read_from_file(**kwargs)

    @classmethod
    def _read_from_file(cls, **kwargs: Any) -> MCPSettings:
        """
        Read MCP settings from the configuration file.

        If the file exists, it is loaded and validated.
        Any additional keys present in the file are preserved.
        Keyword arguments can be used to override values defined in the `mcp_settings.json` file.
        """
        settings_dict: dict[str, Any] = {}
        if cls.MCP_SETTINGS_PATH.exists():
            try:
                with cls.MCP_SETTINGS_PATH.open(mode="r", encoding="utf-8") as f:
                    settings_dict = json.load(f)
            except (json.JSONDecodeError, OSError) as e:
                logging.warning(
                    "Error reading MCP settings file at %s: %s. Starting with default settings.",
                    cls.MCP_SETTINGS_PATH,
                    e,
                )
        else:
            logging.info(
                "Creating default MCP settings file at %s", cls.MCP_SETTINGS_PATH
            )
            default_settings = MCPSettings()
            cls.write_to_file(default_settings)
            settings_dict = default_settings.model_dump()

        # kwargs will override values from the file
        settings_dict.update(kwargs)

        return MCPSettings.model_validate(settings_dict)

    @classmethod
    def write_to_file(cls, settings: MCPSettings) -> None:
        """Write MCP settings to the configuration file."""
        try:
            cls.MCP_SETTINGS_PATH.parent.mkdir(parents=True, exist_ok=True)
            settings_json = json.dumps(
                settings.model_dump(mode="json"), indent=4, ensure_ascii=False
            )
            with cls.MCP_SETTINGS_PATH.open(mode="w", encoding="utf-8") as f:
                f.write(settings_json)
        except OSError as e:
            logging.error("Error writing MCP settings to file: %s", e)

    @property
    def mcp_settings(self) -> MCPSettings:
        """Get the current MCP settings."""
        return self._mcp_settings

    @mcp_settings.setter
    def mcp_settings(self, settings: MCPSettings) -> None:
        """Set the MCP settings and persist them to the configuration file."""
        self._mcp_settings = settings
        self.write_to_file(settings)

    def refresh_mcp_settings(self) -> MCPSettings:
        """Refresh MCP settings from the configuration file."""
        self._mcp_settings = self._read_from_file()
        return self._mcp_settings

    def load_with_overrides(self, **cli_overrides: Any) -> MCPSettings:
        """
        Load MCP settings with proper priority handling.

        Priority order (highest to lowest):
        1. Command line arguments (cli_overrides)
        2. Environment variables
        3. Configuration file (already loaded in self._mcp_settings)
        4. Default values (from MCPSettings model)

        Returns:
            The combined MCPSettings instance.
        """
        # Start with config file as base
        combined_dict = self._mcp_settings.model_dump()

        # Load and apply environment variable overrides
        env_overrides = self._load_settings_from_env()
        if env_overrides:
            _merge_nested_dict(combined_dict, env_overrides)

        # Map and apply command line overrides
        mapped_cli_overrides = self._map_cli_args_to_settings(cli_overrides)
        if mapped_cli_overrides:
            _merge_nested_dict(combined_dict, mapped_cli_overrides)

        # Create final settings instance and update the service state
        final_settings = MCPSettings(**combined_dict)
        self._mcp_settings = final_settings
        return final_settings

    @staticmethod
    def _load_settings_from_env() -> dict[str, Any]:
        """Load MCP settings from environment variables."""
        env_vars: dict = {}
        for field_name, field_info in MCPSettings.model_fields.items():
            alias = getattr(field_info, "alias", None)
            if alias and alias in os.environ:
                value = os.environ[alias]
                annotation = getattr(field_info, "annotation", None)
                origin = get_origin(annotation)

                is_json_field = False
                if origin in (dict, list, tuple):
                    is_json_field = True
                elif origin is Union:
                    is_json_field = any(
                        get_origin(arg) in (dict, list, tuple)
                        for arg in get_args(annotation)
                    )

                if is_json_field:
                    try:
                        if (value.startswith("{") and value.endswith("}")) or (
                            value.startswith("[") and value.endswith("]")
                        ):
                            env_vars[field_name] = json.loads(value)
                        elif ":" in value and all(
                            ":" in part for part in value.split(",")
                        ):
                            env_vars[field_name] = {
                                k.strip(): v.strip()
                                for k, v in (p.split(":", 1) for p in value.split(","))
                            }
                        else:
                            env_vars[field_name] = value
                    except (json.JSONDecodeError, ValueError):
                        env_vars[field_name] = value
                else:
                    env_vars[field_name] = value

        if not env_vars:
            return {}

        try:
            # Use MCPSettings to validate and process env vars
            temp_settings = MCPSettings(**env_vars)
            return temp_settings.model_dump(exclude_unset=True)
        except Exception as e:
            logging.warning("Error processing environment variables: %s", e)
            return {}

    @staticmethod
    def _map_cli_args_to_settings(server_kwargs: dict[str, Any]) -> dict[str, Any]:
        """
        Map command line arguments to MCPSettings field names.

        This handles the translation between CLI argument names and settings field names,
        and separates out Uvicorn and httpx-specific configurations.
        """
        mcp_settings_fields = set(MCPSettings.model_fields.keys())
        cli_to_settings_map = {
            "allowed_categories": "allowed_tool_categories",
            "default_categories": "default_tool_categories",
            "no_tool_discovery": "enable_tool_discovery",
            "system_prompt": "system_prompt_file",
            "system-prompt": "system_prompt_file",
            "server_prompts": "server_prompts_file",
            "server-prompts": "server_prompts_file",
        }
        uvicorn_fields = {
            "host",
            "port",
            "log_level",
            "debug",
            "uds",
            "fd",
            "workers",
            "loop",
            "http",
            "env_file",
            "log_config",
            "access_log",
            "use_colors",
            "proxy_headers",
            "server_header",
            "date_header",
            "forwarded_allow_ips",
            "ssl_keyfile",
            "ssl_certfile",
            "ssl_keyfile_password",
            "ssl_version",
            "ssl_cert_reqs",
            "ssl_ca_certs",
            "ssl_ciphers",
            "header",
            "version",
        }
        excluded_fields = {"transport"}
        httpx_fields = {k for k in server_kwargs if k.startswith("httpx_")}

        settings_overrides: dict[str, Any] = {}
        uvicorn_config: dict[str, Any] = {}
        httpx_config: dict[str, Any] = {}

        for key, value in server_kwargs.items():
            if key in excluded_fields or value is None:
                continue

            if key in httpx_fields:
                httpx_key = key.replace("httpx_", "", 1)
                httpx_config[httpx_key] = value
            elif key in uvicorn_fields:
                uvicorn_config[key] = value
            elif key in cli_to_settings_map:
                mapped_key = cli_to_settings_map[key]
                if mapped_key == "enable_tool_discovery":
                    settings_overrides[mapped_key] = not value
                else:
                    settings_overrides[mapped_key] = value
            elif key in mcp_settings_fields:
                settings_overrides[key] = value
            else:
                # Fallback for unknown fields to uvicorn_config
                uvicorn_config[key] = value

        if uvicorn_config:
            settings_overrides.setdefault("uvicorn_config", {}).update(uvicorn_config)
        if httpx_config:
            settings_overrides.setdefault("httpx_client_kwargs", {}).update(
                httpx_config
            )

        return settings_overrides

"""Utilities for handling FastAPI routes."""

import inspect
import re
import sys
from collections.abc import Sequence

from fastapi import FastAPI
from fastapi.routing import APIRoute
from fastmcp.server.openapi import MCPType, RouteMap
from openbb_core.app.service.system_service import SystemService
from pydantic import ValidationError

from openbb_mcp_server.models.mcp_config import MCPConfigModel, validate_mcp_config
from openbb_mcp_server.models.settings import MCPSettings


class ProcessedRouteData:
    """Container for all data collected during route processing."""

    def __init__(self):
        """Initialize with empty lists and dictionaries."""
        self.route_maps: list[RouteMap] = []
        self.route_lookup: dict[tuple[str, str], APIRoute] = {}
        self.removed_routes: list[APIRoute] = []
        self.prompt_definitions: list[dict] = []


def get_api_prefix(settings: MCPSettings | None) -> str:
    """Get normalized API prefix (leading slash, no trailing slash). Prefer settings.api_prefix if present."""
    override = getattr(settings, "api_prefix", None)
    if isinstance(override, str) and override.strip():
        prefix = override
    else:
        prefix = SystemService().system_settings.api_settings.prefix or ""
    prefix = "/" + prefix.lstrip("/")
    if prefix.endswith("/"):
        prefix = prefix[:-1]
    return prefix


def _get_module_exclusion_targets(settings: MCPSettings | None) -> dict[str, str]:
    """Map path segment -> module name. Prefer settings.module_exclusion_map if a dict is provided."""
    override = getattr(settings, "module_exclusion_map", None)
    if isinstance(override, dict) and override:
        # Ensure keys/values are strings
        return {str(k): str(v) for k, v in override.items()}
    return {
        "econometrics": "openbb_econometrics",
        "quantitative": "openbb_quantitative",
        "technical": "openbb_technical",
        "coverage": "openbb_core",
    }


def get_mcp_config(route: APIRoute, *, strict: bool = False) -> MCPConfigModel:
    """
    Read and validate per-route MCP config from openapi_extra.

    Args:
        route: The APIRoute to process.
        strict: If True, raise validation errors. If False, log warnings.

    Returns:
        A validated MCPConfigModel instance.
    """
    extra = route.openapi_extra or {}
    raw_config = extra.get("mcp_config") or extra.get("x-mcp") or {}

    if not isinstance(raw_config, dict):
        if strict:
            raise TypeError("mcp_config must be a dictionary.")
        raw_config = {}

    try:
        return validate_mcp_config(raw_config, strict=strict)
    except (ValidationError, TypeError, ValueError) as e:
        if strict:
            raise e from e
        return MCPConfigModel()


def _get_prompt_configs(route: APIRoute) -> list[dict]:
    """Extract prompt configurations from per-route MCP config.

    Supports a 'prompts' list of dicts.
    Returns a list of prompt configurations.
    """
    mcp_cfg = get_mcp_config(route)
    # Convert PromptConfigModel to dict
    return [p.model_dump() for p in mcp_cfg.prompts] if mcp_cfg.prompts else []


def _create_prompt_definitions_for_route(
    route: APIRoute, settings: MCPSettings | None = None
) -> list[dict]:
    """Create prompt definitions for a route if prompt configs exist."""
    prompt_configs = _get_prompt_configs(route)
    definitions: list[dict] = []

    if not prompt_configs:
        return definitions

    # Get argument definitions from the endpoint's signature
    # This provides the ground truth for parameter names, types, and defaults
    try:
        sig = inspect.signature(route.endpoint)
        endpoint_args = {
            p.name: {
                "name": p.name,
                "type": (
                    p.annotation.__name__
                    if hasattr(p.annotation, "__name__")
                    else "str"
                ),
                "default": p.default if p.default is not p.empty else ...,
            }
            for p in sig.parameters.values()
            if p.kind in (p.POSITIONAL_OR_KEYWORD, p.KEYWORD_ONLY)
        }
    except (ValueError, TypeError):
        # Cannot inspect signature
        endpoint_args = {}

    # Common info for all prompts on this route
    api_prefix = get_api_prefix(settings)
    tool_uri = route.path.replace(api_prefix, "").lstrip("/").replace("/", "_")
    path = route.path or ""
    if not path.startswith("/"):
        path = "/" + path
    remainder = (
        path[len(api_prefix) :] if api_prefix and path.startswith(api_prefix) else path
    )
    local_path = remainder.lstrip("/")
    segments = [seg for seg in local_path.split("/") if seg and "{" not in seg]

    if segments:
        category = segments[0]
        if len(segments) == 1:
            subcategory = "general"
            tool = segments[0]
        elif len(segments) == 2:
            subcategory = "general"
            tool = segments[1]
        else:
            subcategory = segments[1]
            tool = "_".join(segments[2:])
    else:
        category, subcategory, tool = "general", "general", "root"

    for i, prompt_cfg in enumerate(prompt_configs):
        if not prompt_cfg or not prompt_cfg.get("content"):
            continue

        # Generate prompt name
        prompt_name = prompt_cfg.get("name")
        if not prompt_name:
            base_name = (
                f"{category}_{subcategory}_{tool}"
                if subcategory != "general"
                else f"{category}_{tool}"
            )
            # Add index for uniqueness if multiple unnamed prompts exist
            suffix = f"_{i}" if len(prompt_configs) > 1 else ""
            prompt_name = f"{base_name}_prompt{suffix}"

        # Arguments for the prompt can be a combination of endpoint args and custom ones
        final_args: dict = {}
        prompt_arg_defs = {arg["name"]: arg for arg in prompt_cfg.get("arguments", [])}
        content = (
            f"Use the tool, {tool_uri}, to perform the following task.\n\n"
            + prompt_cfg.get("content", "")
        )

        # All variables in the content string are considered arguments for the prompt
        prompt_vars = re.findall(r"\{(\w+)\}", content)

        for var in set(prompt_vars):
            if var in prompt_arg_defs:
                # Use the definition from the prompt's own 'arguments' list
                final_args[var] = prompt_arg_defs[var]
            elif var in endpoint_args:
                # Inherit the definition from the endpoint's signature
                final_args[var] = endpoint_args[var]
            else:
                # Argument is required by prompt but not defined anywhere
                final_args[var] = {"name": var, "type": "str"}

        # Build prompt definition
        prompt_def = {
            "name": prompt_name,
            "description": prompt_cfg.get("description") or f"Prompt for {tool_uri}",
            "content": content,
            "arguments": list(final_args.values()),
            "tool": tool_uri,
        }

        # Add tags, always including the route path
        tags = list(prompt_cfg.get("tags", []))
        if route.path and route.path not in tags:
            tags.insert(0, route.path)
        prompt_def["tags"] = tags

        definitions.append(prompt_def)

    return definitions


def _normalize_methods(methods: Sequence[str] | None) -> list[str]:
    """Uppercase and filter out HEAD/OPTIONS. Return [] if None/empty."""
    if not methods:
        return []
    out = []
    for m in methods:
        if not m:
            continue
        mu = str(m).upper()
        if mu in {"HEAD", "OPTIONS"}:
            continue
        out.append(mu)
    return out


def _methods_from_config_or_route(cfg: MCPConfigModel, route: APIRoute) -> list:
    """Pull methods from cfg.methods if present; otherwise from route.methods."""
    if cfg.methods:
        # Handle the '*' wildcard for all methods
        if any(m.value == "*" for m in cfg.methods):
            return ["*"]
        methods = [m.value for m in cfg.methods]
    else:
        methods = list(route.methods or [])
    return _normalize_methods(methods)


def _resolve_mcp_type(value: str | None) -> MCPType | None:
    if not value:
        return None
    v = value.lower().strip()
    if v == "tool":
        return MCPType.TOOL
    if v == "resource":
        return MCPType.RESOURCE
    if v in {"resource_template", "resource-template"}:
        return MCPType.RESOURCE_TEMPLATE
    return None


def _should_exclude_by_module_and_path(path: str, settings: MCPSettings | None) -> bool:
    """Exclude only specific route trees if the corresponding module is loaded."""
    api_prefix = get_api_prefix(settings)
    targets = _get_module_exclusion_targets(settings)

    # Normalize path to avoid double slashes annoyance
    if not path.startswith("/"):
        path = "/" + path

    for segment, module_name in targets.items():
        base = f"{api_prefix}/{segment}"
        if path.startswith(base) and module_name in sys.modules:
            return True
    return False


def process_fastapi_routes_for_mcp(
    app: FastAPI, settings: MCPSettings | None = None
) -> ProcessedRouteData:
    """Single-pass processing of FastAPI routes that:

    1. Removes unwanted routes from the app in-place
    2. Builds route maps for FastMCP
    3. Creates route lookup dictionary for customization
    """
    processed = ProcessedRouteData()
    routes_to_keep = []

    for route in app.router.routes:
        if not isinstance(route, APIRoute):
            routes_to_keep.append(route)  # keep non-HTTP routes
            continue

        # Check if route should be excluded
        cfg = get_mcp_config(route)
        should_exclude = False

        # Explicit per-route exposure control
        if cfg.expose is False or _should_exclude_by_module_and_path(
            route.path or "", settings
        ):
            should_exclude = True

        if should_exclude:
            processed.removed_routes.append(route)
            continue

        # Keep the route
        routes_to_keep.append(route)

        # Build route lookup for customization (only for kept routes)
        for method in route.methods or []:
            method_upper = str(method).upper()
            if method_upper not in {"HEAD", "OPTIONS"}:
                processed.route_lookup[(route.path, method_upper)] = route

        # Build route maps for FastMCP (only for routes with explicit mcp_type)
        mcp_type_str = cfg.mcp_type.value if cfg.mcp_type else None
        mcp_type = _resolve_mcp_type(mcp_type_str)
        if mcp_type is not None:
            methods = _methods_from_config_or_route(cfg, route)
            pattern = f"^{re.escape(route.path)}$"
            if methods:
                processed.route_maps.append(
                    RouteMap(pattern=pattern, methods=methods, mcp_type=mcp_type)
                )
            else:
                processed.route_maps.append(
                    RouteMap(pattern=pattern, mcp_type=mcp_type)
                )

        # Collect prompt definitions (only for routes with prompt config)
        prompt_defs = _create_prompt_definitions_for_route(route, settings)
        if prompt_defs:
            processed.prompt_definitions.extend(prompt_defs)

    # Update the app's routes in-place
    app.router.routes = routes_to_keep

    # Add catch-all route map
    catchall_type = (
        _resolve_mcp_type(getattr(settings, "default_catchall_mcp_type", None))
        or MCPType.TOOL
    )
    processed.route_maps.append(RouteMap(pattern=r".*", mcp_type=catchall_type))

    return processed

