from typing import Any

from openbb_core.provider.abstract.data import Data
from pydantic import AliasGenerator, ConfigDict, Field, field_validator
from pydantic.alias_generators import to_snake


class OmniWidgetInput(Data):
    """Input for OmniWidget."""

    model_config = ConfigDict(
        extra="allow",
        alias_generator=AliasGenerator(to_snake),
        title="OmniWidget Input Data for POST Request.",
        json_schema_extra={
            "x-widget_config": {
                "$.type": "omni",
            }
        },
    )

    prompt: Any | None = Field(
        default=None,
        description="The prompt text or JSON object sent from Workspace.",
        json_schema_extra={
            "x-widget_config": {
                "type": "text",
                "value": "",
                "description": "Input prompt value for the OmniWidget.",
                "show": False,
            }
        },
    )

    @field_validator("prompt", mode="before")
    @classmethod
    def _validate_prompt(cls, v):
        """Validate and parse the prompt field."""
        # pylint: disable=import-outside-toplevel
        import json
        import re

        if not v or v == "":
            return None

        prompt = ""

        try:
            prompt = json.loads(v)
        except json.JSONDecodeError:
            # Try to fix common JSON errors like trailing commas
            try:
                # Remove trailing commas in objects and arrays
                cleaned_prompt = re.sub(r",(\s*[}\]])", r"\1", prompt)
                prompt = json.loads(cleaned_prompt)
            except json.JSONDecodeError:
                prompt = v

        return prompt if prompt != "" else None

"""Helper module for merging multiple Fast API endpoints returning agents.json"""

from fastapi import FastAPI
from fastapi.routing import APIRoute


def has_additional_agents(app: FastAPI) -> bool:
    """Check for the existence of additional agents.json endpoints."""
    for route in app.routes:
        if not isinstance(route, APIRoute):
            continue
        path = getattr(route, "path", "")
        if path == "/agents.json":
            continue
        if path.endswith("agents.json"):
            return True
    return False


async def get_additional_agents(app: FastAPI) -> dict:
    """Collect agents.json from non-root endpoints."""
    # pylint: disable=import-outside-toplevel
    from starlette.routing import BaseRoute

    if not has_additional_agents(app):
        return {}

    agents_routes: list[BaseRoute] = []
    for d in app.routes:
        d_path = getattr(d, "path", "")
        if d_path not in {"/agents.json", ""} and d_path.endswith("agents.json"):
            agents_routes.append(d)

    path_agents: dict = {}

    for r in agents_routes:
        if not getattr(r, "endpoint", None) or getattr(r, "path", "") == "/agents.json":
            continue

        agents = await r.endpoint()  # type: ignore

        if not isinstance(agents, dict):
            continue

        path = getattr(r, "path", "").replace("agents.json", "")
        for k, v in agents.copy().items():
            endpoints = v.get("endpoints", {})
            for name, endpoint in endpoints.items():
                if endpoint.startswith("/") and not endpoints.startwith(path):
                    new_endpoint = path + endpoint[1:]
                    agents[k][v]["endpoints"][name] = new_endpoint

        path_agents[path] = agents

    return path_agents

